        "@type": "Organization",
        "name": "Pocketpills",
        "url": "https://www.pocketpills.com/",
        "description": "Canada's largest online pharmacy, expanding into telehealth and virtual care alongside its prescription management platform.",
        "industry": "Healthcare / Pharmacy"
      },
      "keywords": [
        "Brand Refresh",
        "Web Design",
        "Motion Design",
        "Healthcare Branding",
        "Pharmacy Branding",
        "Design System",
        "Telehealth Platform Design",
        "Brand Inflection Point"
      ],
      "workExample": [
        {
          "@type": "CreativeWork",
          "name": "Brand Refresh",
          "description": "A brand refresh anchored in trust, convenience, and innovation — balancing the rigour of healthcare with the clarity and ease of a modern tech platform, as Pocketpills expanded from online pharmacy into a full telehealth offering."
        },
        {
          "@type": "CreativeWork",
          "name": "Website Redesign",
          "description": "A website redesign optimised for both customer confidence and conversion, creating a unified digital experience that makes managing prescriptions and virtual care effortless. Delivered in close collaboration with Pocketpills' in-house development team."
        },
        {
          "@type": "CreativeWork",
          "name": "Motion Design System",
          "description": "A motion design system built to bring the refreshed brand identity to life across the digital platform, reinforcing Pocketpills' positioning as an innovative, modern healthcare experience."
        },
        {
          "@type": "CreativeWork",
          "name": "Scalable Design System",
          "description": "A scalable design system that positions Pocketpills as more than a pharmacy — elevating it into a comprehensive healthcare platform built for future growth."
        }
      ],
      "provider": {
        "@id": "https://gimetry.online/#organization"
      }
    }
  ]
}

